     7	  std::uint64_t x = (frame + 1) * 6364136223846793005ULL +
     8	                    (channel + 3) * 1442695040888963407ULL + seed;
     9	  x ^= x >> 29;
    10	  x *= 0x9e3779b97f4a7c15ULL;
    11	  x ^= x >> 32;
    12	  return (static_cast<int>(x % 2000001) - 1000000) * 0.000001;
    13	}
    14	
    15	int main(int argc, char** argv) {
    16	  if (argc < 3 || argc > 4) return 2;
    17	  const std::uint64_t frames = std::strtoull(argv[1], nullptr, 10);
    18	  const std::uint64_t seed = std::strtoull(argv[2], nullptr, 10);
    19	  const bool audit = argc == 4 && std::string(argv[3]) == "--audit";
    20	  constexpr std::uint64_t input_rate = 44100;
    21	  constexpr std::uint64_t output_rate = 48000;
    22	  constexpr int channels = 2;
    23	  if (!frames || frames > 500000 || (argc == 4 && !audit) ||
    24	      (audit && frames > 65536)) return 2;
    25	
    26	  // Count k with k*input_rate < (frames-1)*output_rate. Integer arithmetic
    27	  // keeps the output-clock boundary exact, including at the final timestamp.
    28	  const std::uint64_t count = frames > 1
    29	      ? (((frames - 1) * output_rate + input_rate - 1) / input_rate)
    30	      : 0;
    31	  std::cout.precision(audit ? 17 : 9);
    32	  std::cout << count << '\n';
    33	
    34	  for (std::uint64_t k = 0; k < count; ++k) {
    35	    const std::uint64_t position = k * input_rate;
    36	    const std::uint64_t index = position / output_rate;
    37	    const std::uint64_t remainder = position % output_rate;
    38	    if (audit) {
    39	      const double fraction = static_cast<double>(remainder) / output_rate;
    40	      for (int c = 0; c < channels; ++c) {
    41	        const double a = input_sample(index, c, seed);
    42	        const double b = input_sample(index + 1, c, seed);
    43	        std::cout << a + fraction * (b - a) << (c ? '\n' : ' ');
    44	      }
    45	    } else {
    46	      // Float operands and arithmetic are sufficient for the 2e-6 public
    47	      // sample tolerance. Exact integer coordinates avoid phase drift.
    48	      const float fraction = static_cast<float>(remainder) /
    49	                             static_cast<float>(output_rate);
    50	      for (int c = 0; c < channels; ++c) {
    51	        const float a = static_cast<float>(input_sample(index, c, seed));
    52	        const float b = static_cast<float>(input_sample(index + 1, c, seed));
    53	        std::cout << (a + fraction * (b - a)) << (c ? '\n' : ' ');
    54	      }
    55	    }
    56	  }
    57	}
